import java.util.*;class TaskBinding{static Object customer(long id,String last,String first,String middle,String card){return new Customer(id,last,first,middle,"Addr"+id,card,"AC"+id);}static Object shortValue(){return new Customer(9,"Short");}static Object[]array(Object...a){return Arrays.copyOf(a,a.length,Customer[].class);}static Object[]sorted(Object[]a){return Customer.sorted((Customer[])a);}static Object[]range(Object[]a,String lo,String hi){return Customer.range((Customer[])a,lo,hi);}static List<?>value(Object x){Customer c=(Customer)x;return List.of(c.id(),c.last(),c.first(),c.middle(),c.address(),c.card(),c.account());}static void edit(Object x){Customer c=(Customer)x;c.id(7);c.last("L");c.first("F");c.middle("M");c.address("A");c.card("0000000000000007");c.account("0007");}static String text(Object x){return x.toString();}}
